-- 14. CONCLUSION (CategoryId = 14)
('Goodbye', 'Thank you for chatting with me! 👋 I hope I was able to help you learn more about AUNG. If you have more questions later, feel free to come back anytime. Good luck with your learning journey! Happy learning! 🌟', 14, 'goodbye, bye, see you, farewell, exit, end chat', 10, true, NOW(), NOW()),
('Bye', 'Bye! 👋 Thanks for visiting AUNG! I hope you found the information you were looking for. Remember, you can always come back if you have more questions. Best of luck with your learning! Take care! 🌟', 14, 'bye, goodbye, see you, farewell, exit, end chat', 10, true, NOW(), NOW()),
('Thank you', 'You''re very welcome! 😊 I''m glad I could help. If you have any more questions about AUNG, courses, or learning, don''t hesitate to ask. Good luck with your learning journey, and I hope to chat with you again soon! 🌟', 14, 'thank you, thanks, appreciate, grateful, thank', 10, true, NOW(), NOW()),
('Thanks', 'You''re welcome! 😊 Happy to help! If you need anything else about AUNG or our courses, just ask. Wishing you success in your learning journey. Feel free to come back anytime! 🌟', 14, 'thanks, thank you, appreciate, grateful, thank', 10, true, NOW(), NOW()),
('End chat', 'Thank you for using AUNG''s chat support! 👋 I hope I was helpful. If you have more questions in the future, I''ll be here to assist. Good luck with your learning journey, and remember - we''re here to support your growth! 🌟', 14, 'end chat, close chat, finish, done, end conversation', 10, true, NOW(), NOW()),
('Done', 'Great! I''m glad I could assist you today. 😊 If you have any more questions about AUNG, courses, or learning, feel free to come back. Best wishes for your learning journey! Happy learning! 🌟', 14, 'done, finished, complete, all done, that''s all', 9, true, NOW(), NOW()),
('That''s all', 'Perfect! Thanks for chatting with me! 👋 I hope you found everything you needed. If you think of any other questions later, don''t hesitate to ask. Good luck with your learning, and I hope to help you again soon! 🌟', 14, 'that''s all, all done, nothing else, finished, complete', 9, true, NOW(), NOW())

) AS new_faqs("Question", "Answer", "CategoryId", "Keywords", "Priority", "IsActive", "CreatedAt", "UpdatedAt")
